import {createStarfield} from './map-layouts.js';
import {BOSS_HP} from './balance.js';
export const WORLD={w:6200,h:2200,id:'meadow'};
export const BUILDINGS=[{x:410,y:365,w:215,d:150,h:115,name:'晴岚驿站'},{x:820,y:340,w:180,d:135,h:96,name:'星灯商会'},{x:330,y:830,w:190,d:140,h:100,name:'林间小屋'}];
export const LAKE={x:970,y:1020,rx:310,ry:210};
export const INTERACTS=[{id:'station',x:575,y:510,name:'站务员 · 林恩',icon:'!',sprite:10},{id:'march',x:730,y:745,name:'三月七 · 合影',icon:'◎',sprite:1},{id:'fish',x:825,y:1050,name:'湖畔钓鱼',icon:'⌁'},{id:'slots',x:875,y:490,name:'星灯游艺机',icon:'♧'},{id:'beacon',x:5790,y:680,name:'断裂的星轨锚点',icon:'✦'},{id:'chest1',x:1430,y:530,name:'旧路旁的宝箱',icon:'▣'},{id:'chest2',x:1860,y:1250,name:'林间宝箱',icon:'▣'},{id:'endless',x:2930,y:555,name:'长风原野 · 无尽试炼',icon:'∞'},{id:'chest3',x:3690,y:1250,name:'高地补给箱',icon:'▣'},{id:'chest4',x:4850,y:630,name:'远行者的行囊',icon:'▣'}];
export const PATH=[{x:600,y:180,w:120,h:650},{x:320,y:485,w:1100,h:130},{x:595,y:600,w:120,h:600},{x:620,y:820,w:180,h:110},{x:1270,y:500,w:130,h:560},{x:1300,y:940,w:810,h:120},{x:1980,y:510,w:130,h:560},{x:2020,y:470,w:1300,h:150},{x:3190,y:520,w:150,h:600},{x:3220,y:970,w:1150,h:150},{x:4190,y:970,w:150,h:670},{x:4230,y:1490,w:1450,h:150},{x:5510,y:600,w:150,h:1010},{x:4790,y:560,w:810,h:150},{x:4790,y:560,w:150,h:1010},{x:5510,y:615,w:550,h:150}];
export const CAMPS=[
 {id:'c0',x:1460,y:775,n:6,elite:true},{id:'c1',x:1660,y:1060,n:7,elite:true},{id:'c2',x:1840,y:855,n:6,elite:true},{id:'c3',x:2120,y:700,n:6,elite:true},{id:'c4',x:2280,y:665,n:5,elite:true},
 {id:'e0',x:3070,y:580,n:7,endless:true},{id:'e1',x:3265,y:850,n:8,endless:true},{id:'e2',x:3520,y:1050,n:8,endless:true},{id:'e3',x:3850,y:1090,n:9,endless:true},{id:'e4',x:4270,y:1190,n:8,endless:true},{id:'e5',x:4530,y:1570,n:10,endless:true},{id:'e6',x:4900,y:1520,n:9,endless:true},{id:'e7',x:5480,y:1510,n:10,endless:true},{id:'e8',x:5580,y:1030,n:9,endless:true},{id:'e9',x:5410,y:640,n:10,endless:true},{id:'e10',x:4880,y:820,n:9,endless:true}
];
export const CLIFFS=[{x:1450,y:1550,w:650,d:190,h:95},{x:2890,y:1390,w:260,d:360,h:120},{x:3700,y:640,w:550,d:200,h:105},{x:4570,y:400,w:450,d:155,h:135},{x:5860,y:1780,w:330,d:230,h:150}];
export function heightAt(x,y){if(WORLD.id==='starfield')return 0;let h=Math.max(0,Math.min(1,(x-2820)/350))*60;h+=Math.max(0,Math.min(1,(x-3660)/300))*60;return h;}
export function seeded(seed){return()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};}
const random=seeded(8173);
export const TREES=[];
export function pathAt(x,y,pad=0){return PATH.some(p=>x>p.x-pad&&x<p.x+p.w+pad&&y>p.y-pad&&y<p.y+p.h+pad);}
export function inLake(x,y){return Math.hypot((x-LAKE.x)/LAKE.rx,(y-LAKE.y)/LAKE.ry)<.97&&!(x>675&&x<910&&y>1018&&y<1082);}
for(let i=0;i<1700;i++){const x=65+random()*(WORLD.w-130),y=90+random()*(WORLD.h-180);if(CAMPS.some(c=>Math.hypot(x-c.x,y-c.y)<170)||pathAt(x,y,65)||Math.hypot(x-610,(y-630)*1.1)<340||Math.hypot((x-LAKE.x)/LAKE.rx,(y-LAKE.y)/LAKE.ry)<1.3||Math.hypot(x-5870,y-680)<270||BUILDINGS.some(b=>Math.abs(x-b.x)<b.w/2+80&&Math.abs(y-b.y)<b.d/2+100)||CLIFFS.some(b=>Math.abs(x-b.x)<b.w/2+30&&Math.abs(y-b.y)<b.d/2+30)||INTERACTS.some(n=>Math.hypot(x-n.x,y-n.y)<95)||TREES.some(t=>Math.hypot(t.x-x,t.y-y)<75))continue;TREES.push({x,y,s:.8+random()*.4,phase:random()*6.28});}
export const FLOWERS=Array.from({length:2400},()=>({x:random()*WORLD.w,y:random()*WORLD.h,c:random(),s:random()}));
export function blocked(x,y){if(x<35||y<60||x>WORLD.w-35||y>WORLD.h-50)return true;if(inLake(x,y))return true;if(BUILDINGS.some(b=>x>b.x-b.w/2-10&&x<b.x+b.w/2+10&&y>b.y-b.d/2-8&&y<b.y+b.d/2+8))return true;if(CLIFFS.some(b=>Math.abs(x-b.x)<b.w/2+8&&Math.abs(y-b.y)<b.d/2+8))return true;return false;} // Vegetation is traversable; terrain and buildings remain solid.
export function faceToward(a,x,y){const dx=x-a.x,dy=y-a.y;if(Math.abs(dx)+Math.abs(dy)<1)return;a.face=dx<0?-1:1;a.direction=Math.abs(dx)>Math.abs(dy)?dx<0?1:2:dy<0?3:0;}
export function move(a,x,y,dt,speed){const dx=x-a.x,dy=y-a.y,d=Math.hypot(dx,dy);a.moving=false;if(d<3)return;const step=Math.min(d,speed*dt),ox=a.x,oy=a.y;const nx=a.x+dx/d*step,ny=a.y+dy/d*step;if(!blocked(nx,a.y))a.x=nx;if(!blocked(a.x,ny))a.y=ny;if(Math.hypot(a.x-ox,a.y-oy)<step*.15&&a.id!==undefined){for(const turn of [Math.PI/4,-Math.PI/4,Math.PI/2,-Math.PI/2]){const ang=Math.atan2(dy,dx)+turn,tx=ox+Math.cos(ang)*step,ty=oy+Math.sin(ang)*step;if(!blocked(tx,ty)){a.x=tx;a.y=ty;break;}}}a.moving=Math.hypot(a.x-ox,a.y-oy)>.05;if(a.moving)faceToward(a,a.x+(a.x-ox)*20,a.y+(a.y-oy)*20);}
export function zone(x,y){if(WORLD.id==='starfield')return x<850?'星潮旷野 · 归航营地':'星潮旷野 · 无尽战场';return x>4600?'星风回廊 · 无尽试炼':x>3550?'曙光高地 · 无尽试炼':x>2820?'长风原野 · 无尽试炼':x>1920?'裂界遗迹':x>1150?'回声林径':y>930?'镜光湖畔':'晴岚驿站';}
export function spawnCamp(c,wave=1){let es=[];for(let i=0;i<c.n;i++){let a=i*2.399,r=45+Math.sqrt(i)*24,x=c.x+Math.cos(a)*r,y=c.y+Math.sin(a)*r;const elite=(!!c.elite||c.trial&&wave%5===0)&&i===0;let hp=Math.round((elite?180:80)*(1+(wave-1)*.13));es.push({id:`${c.id}-${wave}-${i}`,camp:c.id,wave,x,y,homeX:x,homeY:y,hp,maxHp:hp,elite,endless:!!c.endless,kind:i%3===1?'ranged':'melee',cd:1+i*.3,slow:0,frozen:0,dot:0,r:elite?21:17,direction:0,cast:0,damageScale:1+(wave-1)*.035});}return es;}
export function makeEnemies(){let es=CAMPS.filter(c=>!c.endless).flatMap(c=>spawnCamp(c));if(WORLD.id==='meadow')es.push({id:'boss',x:5870,y:680,homeX:5870,homeY:680,hp:BOSS_HP,maxHp:BOSS_HP,boss:true,kind:'boss',cd:3,slow:0,frozen:0,dot:0,r:48,direction:0,cast:0});return es;}

const meadow=structuredClone({world:WORLD,buildings:BUILDINGS,lake:LAKE,interacts:INTERACTS,paths:PATH,camps:CAMPS,cliffs:CLIFFS,trees:TREES,flowers:FLOWERS});
export function activateMap(id){const d=id==='starfield'?createStarfield():structuredClone(meadow);Object.assign(WORLD,d.world);Object.assign(LAKE,d.lake);for(const [target,key] of [[BUILDINGS,'buildings'],[INTERACTS,'interacts'],[PATH,'paths'],[CAMPS,'camps'],[CLIFFS,'cliffs'],[TREES,'trees'],[FLOWERS,'flowers']])target.splice(0,target.length,...d[key]);}
